//! Parity integration tests for voice audio processing (Spec S-07).
//!
//! Validates exact byte-by-byte SHA-256 parity and exact float equality
//! against Node.js reference generated by `scripts/voice-parity-ref.js`.

use serde::Deserialize;
use sha2::{Digest, Sha256};
use std::fs;
use std::path::{Path, PathBuf};
use voice::audio::{downsample_48k_stereo_to_16k_mono, pcm_rms, pcm_to_wav, slice_pcm};

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ParityData {
    fixtures: Vec<FixtureCase>,
    downsample_cases: Vec<DownsampleCase>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct FixtureCase {
    file: String,
    raw_pcm_sha256: String,
    samples: usize,
    rms: f64,
    slices: Vec<SliceCase>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SliceCase {
    start_ms: u32,
    pre_roll_ms: u32,
    pcm_sha256: String,
    wav_sha256: String,
    pcm_samples: usize,
    wav_bytes: usize,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct DownsampleCase {
    index: usize,
    input_samples: usize,
    output_samples: usize,
    sha256: String,
}

fn sha256_hex(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    format!("{:x}", hasher.finalize())
}

fn pcm_to_bytes(pcm: &[i16]) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(pcm.len() * 2);
    for &sample in pcm {
        bytes.extend_from_slice(&sample.to_le_bytes());
    }
    bytes
}

fn bytes_to_pcm(bytes: &[u8]) -> Vec<i16> {
    let mut pcm = Vec::with_capacity(bytes.len() / 2);
    for &chunk in bytes.as_chunks::<2>().0 {
        pcm.push(i16::from_le_bytes(chunk));
    }
    pcm
}

fn fixtures_dir() -> PathBuf {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(|p| p.parent())
        .and_then(|p| p.parent())
        .expect("Project root not found");
    root.join("test").join("fixtures")
}

#[test]
fn test_audio_fixtures_parity_with_node() {
    let data_str = include_str!("data/audio-parity.json");
    let parity_data: ParityData = serde_json::from_str(data_str).expect("Valid audio-parity.json");

    let f_dir = fixtures_dir();
    assert_eq!(parity_data.fixtures.len(), 11);

    for fixture in &parity_data.fixtures {
        let wav_path = f_dir.join(&fixture.file);
        let wav_bytes = fs::read(&wav_path)
            .unwrap_or_else(|e| panic!("Failed reading {}: {:?}", wav_path.display(), e));

        assert!(wav_bytes.len() > 44, "WAV file too small");
        let raw_bytes = &wav_bytes[44..];
        let pcm = bytes_to_pcm(raw_bytes);

        assert_eq!(pcm.len(), fixture.samples);
        assert_eq!(
            sha256_hex(raw_bytes),
            fixture.raw_pcm_sha256,
            "Raw PCM hash mismatch on {}",
            fixture.file
        );

        // Exact float equality for RMS
        let rms = pcm_rms(&pcm);
        assert_eq!(
            rms, fixture.rms,
            "RMS mismatch on {}: rust={}, node={}",
            fixture.file, rms, fixture.rms
        );

        // Parity on slices
        for slice in &fixture.slices {
            let sliced = slice_pcm(&pcm, slice.start_ms, slice.pre_roll_ms);

            // Verify slice borrows memory from original pcm slice (no copy)
            if !pcm.is_empty() && !sliced.is_empty() {
                let pcm_start = pcm.as_ptr() as usize;
                let pcm_end = pcm_start + pcm.len() * std::mem::size_of::<i16>();
                let sliced_start = sliced.as_ptr() as usize;
                assert!(
                    sliced_start >= pcm_start && sliced_start <= pcm_end,
                    "slice_pcm must return borrowed view from input"
                );
            }

            assert_eq!(sliced.len(), slice.pcm_samples);
            let sliced_bytes = pcm_to_bytes(sliced);
            assert_eq!(
                sha256_hex(&sliced_bytes),
                slice.pcm_sha256,
                "Sliced PCM hash mismatch on {} start_ms={}",
                fixture.file,
                slice.start_ms
            );

            // Verify WAV generation byte by byte
            let wav_out = pcm_to_wav(sliced, 16000, 1);
            assert_eq!(wav_out.len(), slice.wav_bytes);
            assert_eq!(
                sha256_hex(&wav_out),
                slice.wav_sha256,
                "WAV container hash mismatch on {} start_ms={}",
                fixture.file,
                slice.start_ms
            );
        }
    }
}

#[test]
fn test_downsample_1000_synthetic_cases_parity() {
    let data_str = include_str!("data/audio-parity.json");
    let parity_data: ParityData = serde_json::from_str(data_str).expect("Valid audio-parity.json");

    assert_eq!(parity_data.downsample_cases.len(), 1000);

    let mut rng_state: u32 = 0x12345678;
    let mut next_u32 = || {
        rng_state ^= rng_state << 13;
        rng_state ^= rng_state >> 17;
        rng_state ^= rng_state << 5;
        rng_state
    };

    for case in &parity_data.downsample_cases {
        let sample_count = (next_u32() % 200) as usize;
        assert_eq!(sample_count, case.input_samples);

        let mut pcm = Vec::with_capacity(sample_count);
        for _ in 0..sample_count {
            let u16_val = (next_u32() & 0xFFFF) as u16;
            pcm.push(u16_val as i16);
        }

        let out = downsample_48k_stereo_to_16k_mono(&pcm);
        assert_eq!(
            out.len(),
            case.output_samples,
            "Sample count mismatch in case {}",
            case.index
        );

        let out_bytes = pcm_to_bytes(&out);
        assert_eq!(
            sha256_hex(&out_bytes),
            case.sha256,
            "Hash mismatch in downsample case {}",
            case.index
        );
    }
}
